def total_cents(prices, discount_percent):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    for price in prices:
        if isinstance(price, bool) or not isinstance(price, int):
            raise TypeError("prices must contain integers")
        if price < 0:
            raise ValueError("prices must be nonnegative")
    if isinstance(discount_percent, bool) or not isinstance(discount_percent, int):
        raise TypeError("discount_percent must be an integer")
    if discount_percent < 0 or discount_percent > 100:
        raise ValueError("discount_percent must be between 0 and 100")
    discounted_numerator = sum(prices) * (100 - discount_percent)
    return (discounted_numerator + 50) // 100

import math

def binary_loss_grad(logits, targets):
    if not isinstance(logits, list) or not isinstance(targets, list):
        raise ValueError("logits and targets must be lists")
    if not logits or len(logits) != len(targets):
        raise ValueError("logits and targets must be nonempty and equal length")
    for logit in logits:
        if isinstance(logit, bool) or not isinstance(logit, (int, float)) or not math.isfinite(logit):
            raise ValueError("logits must be finite numbers")
    for target in targets:
        if isinstance(target, bool) or target not in (0, 1):
            raise ValueError("targets must be 0 or 1")
    loss = 0.0
    gradients = []
    count = len(logits)
    for logit, target in zip(logits, targets):
        loss += max(0.0, logit) - logit * target + math.log1p(math.exp(-abs(logit)))
        if logit >= 0:
            probability = 1.0 / (1.0 + math.exp(-logit))
        else:
            exponential = math.exp(logit)
            probability = exponential / (1.0 + exponential)
        gradients.append((probability - target) / count)
    return loss / count, gradients

def check_contract(fn):
    assert fn(0) == 0
    assert fn(50) == 50
    assert fn(100) == 100
    assert fn(-1) == 0
    assert fn(-1000) == 0
    assert fn(101) == 100
    assert fn(1000) == 100

    for invalid in (1.5, "50", None, [], {}, True, False):
        try:
            fn(invalid)
        except TypeError:
            pass
        except Exception as error:
            raise AssertionError("wrong exception type") from error
        else:
            raise AssertionError("invalid input was accepted")
